import java.util.Scanner;

public class LuckyTickets {

    private static final int MOD = 998244353;
    private static final int TWO_POW = 23;
    private static final int ROOT = 15311432;

    private static int bitReverse(int value, int bitCount) {
        return Integer.reverse(value) >>> (32 - bitCount);
    }

    private static long fastPow(long base, long exponent) {
        long result = 1;
        base %= MOD;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exponent >>= 1;
        }
        return result;
    }

    private static long modInverse(long number) {
        return fastPow(number, MOD - 2);
    }

    private static long[] computePrimitiveRoots(int k, boolean isInverse) {
        long root = fastPow(ROOT, fastPow(2, TWO_POW - k));
        if (isInverse) {
            root = modInverse(root);
        }
        long[] roots = new long[k];
        roots[k - 1] = root;
        for (int i = k - 1; i > 0; i--) {
            roots[i - 1] = (roots[i] * roots[i]) % MOD;
        }
        return roots;
    }

    private static long[] applyBitReversal(long[] input, int k) {
        long[] output = new long[input.length];
        for (int i = 0; i < input.length; i++) {
            output[bitReverse(i, k)] = input[i];
        }
        return output;
    }

    private static long[] performNTT(long[] coefficients, int k, boolean inverse) {
        coefficients = applyBitReversal(coefficients, k);
        long[] roots = computePrimitiveRoots(k, inverse);
        for (int stage = 0; stage < k; stage++) {
            int groupSize = 1 << stage;
            for (int groupStart = 0; groupStart < coefficients.length; groupStart += 2 * groupSize) {
                long omega = 1;
                for (int j = groupStart; j < groupStart + groupSize; j++) {
                    long temp = (omega * coefficients[j + groupSize]) % MOD;
                    long u = coefficients[j];
                    coefficients[j] = (u + temp) % MOD;
                    coefficients[j + groupSize] = (u - temp) % MOD;
                    omega = (roots[stage] * omega) % MOD;
                }
            }
        }
        return coefficients;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int halfN = scanner.nextInt() / 2;
        int m = scanner.nextInt();
        int[] numbers = new int[m];
        int maxNumber = 0;
        for (int i = 0; i < m; i++) {
            numbers[i] = scanner.nextInt();
            maxNumber = Math.max(maxNumber, numbers[i]);
        }
        int minimumSize = halfN * maxNumber + 1;
        int k = 0;
        int size = 1;
        while (size < minimumSize) {
            size <<= 1;
            k++;
        }
        long[] polynomial = new long[size];
        for (int number : numbers) {
            polynomial[number] = 1;
        }
        polynomial = performNTT(polynomial, k, false);
        for (int i = 0; i < size; i++) {
            polynomial[i] = fastPow(polynomial[i], halfN);
        }
        polynomial = performNTT(polynomial, k, true);
        long answer = 0;
        for (int i = 0; i < size; i++) {
            answer = (answer + polynomial[i] * polynomial[i]) % MOD;
        }
        long divisor = modInverse(size);
        System.out.println(((answer * divisor % MOD) * divisor) % MOD);
    }
}
